const now = new Date();
const msk = new Date(now.getTime() + 3 * 60 * 60 * 1000);
const day = new Date(Date.UTC(msk.getUTCFullYear(), msk.getUTCMonth(), msk.getUTCDate() - 1));
const start = new Date(day); start.setUTCDate(start.getUTCDate() - 29);
const financeStart = new Date(day); financeStart.setUTCDate(financeStart.getUTCDate() - 13);
const end = new Date(day); end.setUTCHours(23, 59, 59, 999);
const businessDate = day.toISOString().slice(0, 10);
return [{json: {business_date: businessDate, collection_ref: `operational-daily:${businessDate}:${$execution.id}`, started_at: now.toISOString(), postings_from: start.toISOString(), returns_from: start.toISOString(), finance_from: financeStart.toISOString(), window_to: end.toISOString(), mode: 'DAILY'}}];

const ctx = $('Collection Context').first().json;
const pages = $input.all().map(i => i.json);
const failed = pages.find(x => x?.error);
const errorText = failed ? String(failed.error?.message ?? failed.error ?? 'Unknown HTTP error').slice(0, 2000) : null;
if (failed || !pages.length || pages.some(x => !Array.isArray(x?.result?.postings))) return [{json: {...ctx, source: 'POSTINGS', ok: false, status: 'FAILED', pages_count: pages.length, records_count: 0, error_message: errorText ?? 'Unexpected postings response contract', window_from: ctx.postings_from, window_to: ctx.window_to, rows: []}}];
const unique = new Map();
for (const page of pages) for (const posting of page.result.postings) for (const product of (posting.products ?? [])) {
  const row = {posting_number: posting.posting_number, order_number: posting.order_number ?? null, status: posting.status ?? null, offer_id: product.offer_id, sku: product.sku ?? null, name: product.name ?? null, quantity: product.quantity ?? null, shipment_date: posting.shipment_date ?? null, delivering_date: posting.delivering_date ?? null, updated_from_ozon: new Date().toISOString(), in_process_at: posting.in_process_at || null};
  if (row.posting_number && row.offer_id) unique.set(`${row.posting_number}\u0000${row.offer_id}`, row);
}
const rows = [...unique.values()];
return [{json: {...ctx, source: 'POSTINGS', ok: true, status: rows.length ? 'SUCCESS' : 'SUCCESS_ZERO', pages_count: pages.length, records_count: rows.length, error_message: null, window_from: ctx.postings_from, window_to: ctx.window_to, rows}}];

const data = $input.first().json;
if (!data.rows.length) return [{json: {is_zero: true}}];
return data.rows.map(row => ({json: {...row, is_zero: false}}));

