const ctx = $('Collection Context').first().json;
let cursor = new Date(ctx.finance_from);
const inclusiveEnd = new Date(ctx.window_to);
const exclusiveEnd = new Date(inclusiveEnd.getTime() + 1);
const rows = [];
while (cursor < exclusiveEnd && rows.length < 24) {
  const monthEnd = new Date(Date.UTC(cursor.getUTCFullYear(), cursor.getUTCMonth() + 1, 1));
  const next = monthEnd < exclusiveEnd ? monthEnd : exclusiveEnd;
  rows.push({json: {...ctx, finance_window_from: cursor.toISOString(), finance_window_to: new Date(next.getTime() - 1).toISOString()}});
  cursor = next;
}
if (!rows.length || cursor < exclusiveEnd) throw new Error('Invalid or unbounded finance month windows');
return rows;

